        private static void TestNamesPipe() {
            var pipeName = "Bob";
            var server = new NamedPipesIMessageProcessorReceiverV1(new CoreMessageProcessor(), pipeName, 1024, 4096);
            server.Start();
            var client = new NamedPipesIMessageProcessorSenderV1(pipeName, 128);

            //send a 100,000 method enter and exit events
            for (int i = 0; i < 100000; i++) {
                client.OnMethodEntered(12, 24, 36, Stopwatch.GetTimestamp(), 60);
                client.OnMethodExited(12, 24, 36, Stopwatch.GetTimestamp(), 60);
            }

            client.Stop(0, Stopwatch.GetTimestamp());
            server.Stop();
            Console.WriteLine("");
        }

