        private static void RunTests() {

            try {


                ////register the default.
                //var builder = new ContainerBuilder();
                //Debug.WriteLine("new ContainerBuilder");
                //builder.RegisterType<SqLiteIMessageProcessor>().As<IMessageProcessor>().SingleInstance();
                //builder.RegisterType<CoreClientMessageService>().As<IClientMessageService>().SingleInstance();
                //Debug.WriteLine("RegisterType SqLiteIClientMessageService as IClientMessageService");

                //var container = builder.Build();

                //Debug.WriteLine("Resolve IClientMessageService");
                //Messaging.Service = container.Resolve<IClientMessageService>();
                //Debug.WriteLine("IClientMessageService" + Messaging.Service != null ? Messaging.Service.GetType().FullName : "<none>");
                //container.Dispose();

                //see what the opcode is to load a field and call a method

                //This app is designed to allow us to use ants to run the unit tests and grab timing data
                var sw = new Stopwatch();
                sw.Start();
                int totalTests = 0;

                var types = typeof(TestPlaceHolder).Assembly
                                                .GetTypes()
                                                .Where(t => t.GetCustomAttributes(typeof(TestClassAttribute), true).Any()
                                                        && !t.IsAbstract)
                                                .ToList();

                foreach (var type in types) {

                    //create the type

                    var runner = Activator.CreateInstance(type);

                    Console.WriteLine("Loading Type:" + type.FullName);

                    //see if we have a ClassInitialize
                    var classInitialize = type.GetMethods()
                                           .Where(t => t.GetCustomAttributes(typeof(ClassInitializeAttribute), true).Any())
                                           .FirstOrDefault();

                    if (classInitialize != null) {

                        //see if a property exists

                        TestContext tc = default(TestContext);

                        var tempTC = type.GetProperty("TestContext", System.Reflection.BindingFlags.FlattenHierarchy | System.Reflection.BindingFlags.Default);

                        if (tempTC != null) {
                            var gm = tempTC.GetGetMethod();
                            tc = gm.Invoke(runner, new object[] { }) as TestContext;
                        }

                        classInitialize.Invoke(runner, new object[] { tc });
                    }

                    var methods = type.GetMethods()
                        .Where(t => t.GetCustomAttributes(typeof(TestMethodAttribute), true).Any()
                                && !t.GetCustomAttributes(typeof(IgnoreAttribute), true).Any())
                        .ToList();

                    foreach (var method in methods) {
                        Console.WriteLine("Running Method" + method.Name);

                        //see if we have a TestInitializeAttribute
                        var testInitialize = type.GetMethods()
                                               .Where(t => t.GetCustomAttributes(typeof(TestInitializeAttribute), true).Any())
                                               .FirstOrDefault();

                        if (testInitialize != null) {
                            testInitialize.Invoke(runner, null);
                        }

                        try {
                            totalTests++;
                            method.Invoke(runner, null);
                        }
                        catch (Exception ex) {
                            Console.WriteLine(ex.ToString());
                        }

                        //see if we have a TestInitializeAttribute
                        var testCleanup = type.GetMethods()
                                               .Where(t => t.GetCustomAttributes(typeof(TestCleanupAttribute), true).Any())
                                               .FirstOrDefault();

                        if (testCleanup != null) {
                            testCleanup.Invoke(runner, null);
                        }
                    }

                    //see if we have a ClassCleanup
                    var classCleanup = type.GetMethods()
                                          .Where(t => t.GetCustomAttributes(typeof(ClassCleanupAttribute), true).Any())
                                          .FirstOrDefault();

                    if (classCleanup != null) {
                        classCleanup.Invoke(runner, null);
                    }

                }

                Console.WriteLine(totalTests + " Tests Done!");
                Console.WriteLine("Total Time:" + sw.ElapsedMilliseconds);
                //commented out because we want to actually test with the real message bus.
                //Messaging.Stop();
                //sw.Stop();
                //Console.WriteLine("Total Time With Db Save:" + sw.ElapsedMilliseconds);          
            }
            catch (ReflectionTypeLoadException ex) {
                Debug.WriteLine(ex.ToString());
                Debug.WriteLine("----- LoaderExceptions:");
                for (int i = 0; i < ex.LoaderExceptions.Length; i++) {
                    Debug.WriteLine(ex.LoaderExceptions[i]);
                }
                Debug.WriteLine("--------------------");
            
                Console.WriteLine(ex.ToString());
                Console.WriteLine("----- LoaderExceptions:");
                for (int i = 0; i < ex.LoaderExceptions.Length; i++) {
                    Console.WriteLine(ex.LoaderExceptions[i]);
                }
                Console.WriteLine("--------------------");
            }
            catch (Exception ex) {
                Debug.WriteLine(ex.ToString());
                Console.WriteLine(ex.ToString());
            }
        }

        private static void CreateTestClasses() {
            var path = @"C:\dev\NetPerf\NetPerf.Tests.Integration\CallGraphTestClassesNS\TestGen.cs";

            using (var sw = new StreamWriter(path)) {

                sw.WriteLine(@"using System;
using System.Diagnostics;
using System.Text;
using System.Collections.Generic;
using System.Linq;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using System.Reflection;
using NetPerf.Common.Instrumentation;
using CallGraphTestClasses;

namespace NetPerf.Tests.Integration.CallGraphTestClassesNS {
");

                //var types = typeof(TopLevelClassWithChildrenBase).Assembly
                //    .GetTypes().Where(item => item.FullName.StartsWith("CallGraphTestClasses.NormalClassGenericChildClass")).ToList();

                var types = new Type[] {
                                            typeof(RecursiveClassBase),
                                            typeof(RecursiveClassCallBase),
                                            typeof(RecursiveClassInherited)
                                      };

                sw.WriteLine("");
                sw.WriteLine("[TestClass]");
                sw.WriteLine(string.Format("public class {0}Tests : CallGraphValidateBaseClass {{", "InternalAndPrivateClassHelper")); //have to escape {

                //we are going to create one main method that generates all of the test data.

                sw.WriteLine("[TestMethod]");
                sw.WriteLine("public void Main() {");

                foreach (var type in types) {
                    sw.WriteLine("Main" + FullName(type) + "();");
                }

                sw.WriteLine("} //main");

                foreach (var type in types) {
                    GenerateTestMethodForType(sw, type);
                }


                foreach (var type in types) {
                    GenerateGetInstanceForType(sw, type);
                }

                sw.WriteLine("} //class");
                sw.WriteLine("} //ns");

                sw.BaseStream.SetLength(sw.BaseStream.Position);
            }
        }

        private static void GenerateGetInstanceForType(StreamWriter sw, Type type) {
            sw.WriteLine("");
            sw.WriteLine("");
            sw.WriteLine(@"protected " + type.FullName.Replace("+", ".") + " GetInstance" + FullName(type) + "() {");
            sw.WriteLine(@"return new " + type.FullName.Replace("+", ".") + "();");
            sw.WriteLine("}");
        }

        private static void GenerateTestMethodForType(StreamWriter sw, Type type) {

            sw.WriteLine("");
            sw.WriteLine("public void Main" + FullName(type) + "() {");
            //now for each method, create the code that will help us build the final tester class.

            sw.WriteLine("var instance = GetInstance" + FullName(type) + "();");
            //sw.WriteLine("var type = instance.GetType();");

            foreach (var method in type.GetConstructors()) {
                var paramList = method.GetParameters();
                if (paramList.Count() > 0) {
                    sw.WriteLine("");
                    sw.WriteLine("");
                    //for each method, we want to clear and then capture the data.
                    sw.WriteLine("IntegrationTestIClientMessageService.ClearCalls();");
                    sw.WriteLine("instance." + method.Name + "(enterhere);"); //do we care about params or voids right now?
                    GenerateTestMethodDebugStatements(sw, type, method, true);
                }
            }

            foreach (var method in type.GetMethods()
                .Where(item => item.DeclaringType == type && !item.Name.StartsWith("get_") && !item.Name.StartsWith("set_"))) {

                sw.WriteLine("");
                sw.WriteLine("");

                //for each method, we want to clear and then capture the data.
                sw.WriteLine("IntegrationTestIClientMessageService.ClearCalls();");
                sw.WriteLine("instance." + method.Name + "();");

                GenerateTestMethodDebugStatements(sw, type, method, false);
            }

            sw.WriteLine("} //method");
            //sw.WriteLine("Debug.WriteLine(\"             \");");
        }

        private static void GenerateTestMethodDebugStatements(StreamWriter sw, Type type, MethodBase method, bool ctor) {


            sw.WriteLine("Debug.WriteLine(\"\");");

            sw.WriteLine("Debug.WriteLine(\"[TestMethod]\");");
            sw.WriteLine("Debug.WriteLine(\"public void " + type.Name + "_" + method.Name + "() {\");");

            if (ctor) {
                sw.WriteLine("Debug.WriteLine(\"IntegrationTestIClientMessageService.ClearCalls();\");");
                sw.WriteLine("Debug.WriteLine(\"var instance = new " + type.Name + "(enterhere);\");");
            }
            else {
                sw.WriteLine("Debug.WriteLine(\"var instance = GetInstance" + FullName(type) + "();\");");

                sw.WriteLine("Debug.WriteLine(\"\");");

                //These need to be in the method itself
                sw.WriteLine("Debug.WriteLine(\"//clear after creating.\");");
                sw.WriteLine("Debug.WriteLine(\"IntegrationTestIClientMessageService.ClearCalls();\");");
                sw.WriteLine("Debug.WriteLine(\"instance." + method.Name + "();\");");
            }

            //we want this rendered here.
            sw.WriteLine("Debug.WriteLine(IntegrationTestIClientMessageService.ToTraceStatements(\"" + method.Name + "\"));");

            sw.WriteLine("");
            sw.WriteLine("Debug.WriteLine(\"IntegrationTestIClientMessageService.ValidateCallGraph(tester);\");");

            sw.WriteLine("Debug.WriteLine(\"}\");"); //end of method

            sw.WriteLine("Debug.WriteLine(\"\");");

            sw.WriteLine("");
        }

        public static string FullName(Type type) {
            return type.FullName.Replace(".", "_").Replace("+", "_");
        }

